import { mod, type Mod, type SkillTag } from '../mods/types';
import { BASE_ROWS, type BaseRow } from './baseTables';
import type { ArmourSlot, Attrs, DefenceType, ItemBase, ItemClass, WeaponClass } from './types';

/**
 * Item bases (DESIGN.md §11.2): one for every droppable base of the reference game's 3.9 tables, with its level,
 * requirements, numbers and implicit (docs/AUDIT-ITEM-BASES.md). The rows are `baseTables.ts`, generated by
 * `npm run coverage:emit-bases` from the tables and our names for them (docs/coverage/base-names.json); this file turns
 * them into bases and keeps the ids of the bases the game had before (saves, posted rivals and uniques name them).
 */

/** Every weapon's base damage, as a multiple of the reference numbers: the lever if late weapons prove too strong or weak. */
export const WEAPON_DAMAGE_SCALE = 1;
/** Every base's attribute requirements, as a multiple of the reference numbers. */
export const REQUIREMENT_SCALE = 1;

type WeaponFamilyDef = {
  /** The key of its rows in `BASE_ROWS`, and the prefix of its ids. */
  key: string;
  cls: WeaponClass;
  hands: 1 | 2;
  tags: SkillTag[];
  /** Built for spells: it rolls the spell affixes (`ItemBase.spellWeapon`). */
  spell: boolean;
};

/** The weapon families: the twelve classes, and the three families inside a class (COVERAGE C2). */
export const WEAPON_FAMILIES: WeaponFamilyDef[] = [
  { key: 'sword', cls: 'sword', hands: 1, tags: ['sword', 'oneHand'], spell: false },
  { key: 'thrust', cls: 'sword', hands: 1, tags: ['sword', 'oneHand'], spell: false },
  { key: 'axe', cls: 'axe', hands: 1, tags: ['axe', 'oneHand'], spell: false },
  { key: 'mace', cls: 'mace', hands: 1, tags: ['mace', 'oneHand'], spell: false },
  { key: 'sceptre', cls: 'sceptre', hands: 1, tags: ['sceptre', 'oneHand'], spell: true },
  { key: 'dagger', cls: 'dagger', hands: 1, tags: ['dagger', 'oneHand'], spell: false },
  { key: 'runedagger', cls: 'dagger', hands: 1, tags: ['dagger', 'oneHand'], spell: true },
  { key: 'claw', cls: 'claw', hands: 1, tags: ['claw', 'oneHand'], spell: false },
  { key: 'wand', cls: 'wand', hands: 1, tags: ['wand', 'oneHand'], spell: true },
  { key: 'sword2', cls: 'sword2', hands: 2, tags: ['sword', 'twoHand'], spell: false },
  { key: 'axe2', cls: 'axe2', hands: 2, tags: ['axe', 'twoHand'], spell: false },
  { key: 'mace2', cls: 'mace2', hands: 2, tags: ['mace', 'twoHand'], spell: false },
  { key: 'staff', cls: 'staff', hands: 2, tags: ['staff', 'twoHand'], spell: true },
  { key: 'warstaff', cls: 'staff', hands: 2, tags: ['staff', 'twoHand'], spell: false },
  { key: 'bow', cls: 'bow', hands: 2, tags: ['bow', 'twoHand'], spell: false },
];

const ARMOUR_SLOTS: ArmourSlot[] = ['helmet', 'gloves', 'boots', 'body'];
const DEF_TYPES: DefenceType[] = ['ar', 'ev', 'es', 'arev', 'ares', 'eves'];

/**
 * A bow's reach is the map's, and a wand's the short reach Bob's wand attack has always had (the reference's 120 units is its
 * projectile, which Bob's wand attack is not); a melee weapon's is the reference reach in tiles (about 8.5 units to a tile).
 */
const BOW_RANGE = 9;
const WAND_RANGE = 1.2;
const UNITS_PER_TILE = 8.5;

const req = (r: [number, number, number]): Attrs => ({
  str: Math.round(r[0] * REQUIREMENT_SCALE),
  dex: Math.round(r[1] * REQUIREMENT_SCALE),
  int: Math.round(r[2] * REQUIREMENT_SCALE),
});
const rows = (key: string): BaseRow[] => BASE_ROWS[key] ?? [];

function weaponBases(): ItemBase[] {
  const out: ItemBase[] = [];
  for (const f of WEAPON_FAMILIES)
    for (const r of rows(f.key)) {
      const [min, max, crit, aps, units] = r.weapon!;
      out.push({
        id: r.id,
        name: r.name,
        itemClass: f.cls,
        level: r.level,
        req: req(r.req),
        implicits: r.implicits ?? [],
        weapon: {
          min: Math.round(min * WEAPON_DAMAGE_SCALE),
          max: Math.round(max * WEAPON_DAMAGE_SCALE),
          aps,
          crit,
          range:
            f.cls === 'bow'
              ? BOW_RANGE
              : f.cls === 'wand'
                ? WAND_RANGE
                : Math.round((units / UNITS_PER_TILE) * 10) / 10,
        },
        tags: f.tags,
        hands: f.hands,
        spellWeapon: f.spell,
        ...(r.minion ? { minionWeapon: true } : {}),
      });
    }
  return out;
}

function defenceOf(d: [number, number, number, number]): ItemBase['defence'] {
  const out: NonNullable<ItemBase['defence']> = {};
  if (d[0]) out.armour = d[0];
  if (d[1]) out.evasion = d[1];
  if (d[2]) out.es = d[2];
  if (d[3]) out.block = d[3];
  return out;
}

function armourBases(): ItemBase[] {
  const out: ItemBase[] = [];
  for (const slot of [...ARMOUR_SLOTS, 'shield' as const])
    for (const type of DEF_TYPES)
      for (const r of rows(`${slot}_${type}`))
        out.push({
          id: r.id,
          name: r.name,
          itemClass: slot,
          level: r.level,
          req: req(r.req),
          implicits: r.implicits ?? [],
          defence: defenceOf(r.def!),
          defenceType: type,
          tags: [],
        });
  return out;
}

function jewelleryBases(): ItemBase[] {
  const out: ItemBase[] = [];
  for (const cls of ['ring', 'amulet', 'belt', 'quiver'] as ItemClass[])
    for (const r of rows(cls))
      out.push({
        id: r.id,
        name: r.name,
        itemClass: cls,
        level: r.level,
        req: req(r.req),
        implicits: r.implicits ?? [],
        tags: [],
        ...(r.sockets ? { sockets: r.sockets } : {}),
      });
  return out;
}

/**
 * Bases that never drop: the one uniques alone use, and two bases the reference game does not have, kept for the items on
 * them (a belt of armour, and the flat-accuracy quiver the Strider starts with).
 */
function uniqueBases(): ItemBase[] {
  const none: Attrs = { str: 0, dex: 0, int: 0 };
  return [
    {
      id: 'quiver_acc',
      name: 'Feathered Quiver',
      itemClass: 'quiver',
      level: 1,
      req: none,
      implicits: [mod('accuracy', 'base', 60)],
      tags: [],
      uniqueOnly: true,
    },
    {
      id: 'body_rags',
      name: 'Grave Rags',
      itemClass: 'body',
      level: 1,
      req: none,
      implicits: [],
      tags: [],
      uniqueOnly: true,
    },
    {
      id: 'belt_armour',
      name: 'Plated Girdle',
      itemClass: 'belt',
      level: 10,
      req: none,
      implicits: [mod('armour', 'base', 120)],
      tags: [],
      uniqueOnly: true,
    },
  ];
}

export const ITEM_BASES: ItemBase[] = [
  ...weaponBases(),
  ...armourBases(),
  ...jewelleryBases(),
  ...uniqueBases(),
];

const BASE_BY_ID = new Map(ITEM_BASES.map((b) => [b.id, b]));

/** The base of a family nearest a level (the lower one when two are as near). */
function nearestOf(key: string, level: number): BaseRow | undefined {
  let best: BaseRow | undefined;
  for (const r of rows(key))
    if (!best || Math.abs(r.level - level) < Math.abs(best.level - level)) best = r;
  return best;
}

/**
 * The ids the game used before every reference base was taken on (2026-10-18): four armour tiers at levels 1, 20, 40 and
 * 60, five weapon tiers at 1, 15, 30, 45 and 60. Each stands for the base of its family nearest its level, so a saved or
 * posted item, a unique and a test keep resolving.
 */
const LEGACY_IDS: Map<string, string> = (() => {
  const m = new Map<string, string>();
  const add = (oldId: string, key: string, level: number) => {
    const r = nearestOf(key, level);
    if (r) m.set(oldId, r.id);
  };
  for (const f of WEAPON_FAMILIES)
    [1, 15, 30, 45, 60].forEach((level, i) => add(`${f.key}_${i + 1}`, f.key, level));
  for (const slot of [...ARMOUR_SLOTS, 'shield'])
    for (const type of DEF_TYPES)
      [1, 20, 40, 60].forEach((level, i) =>
        add(`${slot}_${type}_${i + 1}`, `${slot}_${type}`, level),
      );
  return m;
})();

/** The base for an id, old or new. */
export function itemBase(id: string): ItemBase {
  const b = BASE_BY_ID.get(id) ?? BASE_BY_ID.get(LEGACY_IDS.get(id) ?? '');
  if (!b) throw new Error(`unknown item base ${id}`);
  return b;
}

/** The id an old base id stands for today (an unknown id is returned as it is). */
export function canonicalBaseId(id: string): string {
  return BASE_BY_ID.has(id) ? id : (LEGACY_IDS.get(id) ?? id);
}

/** The mods a base's implicit lines give (the pattern uniques and tests use). */
export function baseImplicits(id: string): Mod[] {
  return itemBase(id).implicits;
}

/** What a weapon of each class is called on its card: the type that skills ask for ("needs a bow", "a sword or a dagger"). */
export const WEAPON_TYPE_NAME: Record<WeaponClass, string> = {
  sword: 'One-Handed Sword',
  axe: 'One-Handed Axe',
  mace: 'One-Handed Mace',
  sceptre: 'Sceptre',
  dagger: 'Dagger',
  claw: 'Claw',
  wand: 'Wand',
  sword2: 'Two-Handed Sword',
  axe2: 'Two-Handed Axe',
  mace2: 'Two-Handed Mace',
  staff: 'Staff',
  bow: 'Bow',
};

export function isWeaponClass(c: ItemClass): c is WeaponClass {
  return c in WEAPON_TYPE_NAME;
}
